B2={
'maliang':('馬良','Jichang','187–222',"Best of five talented brothers, known by his white eyebrows.","'Of the five Ma brothers, White Eyebrows is the finest.' He served as envoy to Wu and to the Wuling tribes and was killed at Xiaoting.",["'White Eyebrows'","Envoy to Sun Quan","Won over the Wuling tribes"]),
'pangtong':('龐統','Shiyuan','179–214',"A Xiangyang scholar called the Fledgling Phoenix.","He guided Liu Bei's conquest of Yi province but was killed by an arrow at Luo. The novel credits him with chaining Cao Cao's ships at Red Cliffs.",["'Fledgling Phoenix'","Plan to take Yi province","Chained ships ruse (novel)"]),
'jiangwan':('蔣琬','Gongyan','?–246',"A scholar of Lingling.","Chosen by Zhuge Liang as his successor, he led Shu's government after 234 and kept the state steady.",["Successor to Zhuge Liang","Head of Shu government","Calm under criticism"]),
'liufeng':('劉封','','?–220',"Born Kou Feng, adopted by Liu Bei before Liu Shan was born.","He fought in the conquest of Yi. In 219 he refused to aid Guan Yu and was later forced to take his own life.",["Adopted son of Liu Bei","Took Shangyong","Failed to aid Guan Yu"]),
'guanping':('關平','','?–220',"Guan Yu's son (adopted, in the novel).","He fought at his father's side to the last and was captured and executed with him by Wu at Linju.",["Son of Guan Yu","Fought at Fancheng","Died beside his father"]),
'chendao':('陳到','Shuzhi','?–?',"An officer of Yu province who followed Liu Bei from early days.","He commanded Liu Bei's personal guard and was ranked just after Zhao Yun in fame.",["Commander of the White-Feather Guard","Second only to Zhao Yun","Liu Bei's bodyguard"]),
'zhoucang':('周倉','','fictional',"A former Yellow Turban bandit with immense strength.","In the novel he carried Guan Yu's great blade and captured Pang De. When Guan Yu died he killed himself. He stands beside Guan Di in temples today.",["Carried Guan Yu's blade","Captured Pang De (novel)","Worshipped beside Guan Di"],1),
'liaohua':('廖化','Yuanjian','?–264',"An officer of Guan Yu's in Jingzhou.","He escaped from Wu by faking his own death and lived to see Shu's last days. 'Shu has no great generals, so Liao Hua leads the van.'",["Faked his death to return to Shu","Served Shu to its end","Proverbial veteran"]),
'huojun':('霍峻','Zhongmiao','178–217',"A Nanjun man who brought his clan's troops to Liu Bei.","He held Jiameng Pass for a year with a few hundred men against ten thousand.",["Held Jiameng Pass","Defeated the besiegers","Trusted by Liu Bei"]),
'liuqi':('劉琦','','?–209',"Eldest son of Liu Biao, pushed aside by his stepmother's Cai clan.","Zhuge Liang, trapped by him in an attic with the ladder removed, advised him to leave for Jiangxia. There he sheltered Liu Bei after Changban.",["Took refuge in Jiangxia","Sheltered Liu Bei after Changban","Inspector of Jing province"]),
'yiji':('伊籍','Jibo','?–?',"A Yanzhou man in Liu Biao's service.","He warned Liu Bei of Cai Mao's murder plot, later served as his envoy and helped write Shu's laws.",["Warned Liu Bei of Cai Mao","Envoy to Wu","Co-author of Shu's legal code"]),
'mifang':('糜芳','Zifang','?–?',"Mi Zhu's younger brother.","Left to guard Jiangling, he quarrelled with Guan Yu and surrendered to Lü Meng in 219, dooming Guan Yu.",["Garrisoned Jiangling","Surrendered to Wu","Brother of Mi Zhu"]),
'luxun':('陸遜','Boyan','183–245',"Heir of the great Lu clan of Wu.","His humble letters lulled Guan Yu in 219, and in 222 he burned Liu Bei's camps at Xiaoting. He rose to chancellor of Wu.",["Burned Liu Bei's camps at Xiaoting","Deceived Guan Yu","Chancellor of Wu"]),
'lingtong':('凌統','Gongji','189–217',"Son of Ling Cao, who was killed by Gan Ning's arrow.","He bore a grudge against Gan Ning but fought beside him. At Xiaoyao Ford he lost all his men saving Sun Quan.",["Saved Sun Quan at Xiaoyao","Feud with Gan Ning","Brave at fifteen"]),
'chengpu':('程普','Demou','?–?',"The eldest veteran of Wu, serving since Sun Jian.","He co-commanded at Red Cliffs. Once scornful of young Zhou Yu, he later said serving him 'was like drinking fine wine'.",["Co-commander at Red Cliffs","Veteran of three Sun lords","'Lord Cheng'"]),
'handang':('韓當','Yigong','?–?',"A horse-archer veteran who served Sun Jian.","He fought at Red Cliffs and later against Liu Bei at Xiaoting.",["Veteran since Sun Jian","Fought at Red Cliffs","Fought at Xiaoting"]),
'jiangqin':('蔣欽','Gongyi','?–219',"A Jiujiang man who joined Sun Ce young.","At Sun Quan's urging he took up study. He praised Xu Sheng to Sun Quan despite a quarrel between them.",["Studied at Sun Quan's urging","Recommended his rival Xu Sheng","Fought at Hefei"]),
'zhuzhi':('朱治','Junli','156–224',"An officer of Sun Jian.","He urged Sun Ce to cross the Yangtze and found the south, then governed Wu commandery for decades.",["Urged Sun Ce to cross the river","Governor of Wu commandery","Elder statesman of Wu"]),
'zhugejin':('諸葛瑾','Ziyu','174–241',"Zhuge Liang's elder brother.","He served Wu, and when sent to Shu he met his brother only in public. Sun Quan trusted him completely.",["Elder brother of Zhuge Liang","Envoy to Shu","General of Wu"]),
'kanze':('闞澤','Derun','?–243',"A poor farmer's son who copied books to study.","In the novel he carried Huang Gai's false surrender letter to Cao Cao and talked his way out of execution.",["Self-taught scholar","Delivered Huang Gai's letter (novel)","Tutor to Sun Quan's heir"]),
'xusheng':('徐盛','Wenxiang','?–?',"A Langya man who settled in Wu.","In 224 he built fake walls along the Yangtze at Guangling, and Cao Pi turned back in fear.",["Fake walls at Guangling","Fought at Xiaoting","Bold river commander"]),
'panzhang':('潘璋','Wengui','?–234',"A hard-drinking, free-spending officer.","His men captured Guan Yu in 219.",["His men captured Guan Yu","Fought at Xiaoting","Fierce and greedy"]),
'dongxi':('董襲','Yuandai','?–?',"A huge, strong man of Kuaiji.","In 208 he cut the cables of Huang Zu's chained warships, opening the way to victory. He drowned refusing to abandon his ship in a storm.",["Cut Huang Zu's ship cables","Refused to abandon his ship","Giant of Kuaiji"]),
'zhuran':('朱然','Yifeng','182–249',"Sun Quan's schoolmate.","He helped capture Guan Yu in 219 and held Jiangling against Wei for six months in 223.",["Helped capture Guan Yu","Held Jiangling against Wei","Sun Quan's schoolmate"]),
'simayi':('司馬懿','Zhongda','179–251',"A Henei noble who faked paralysis to dodge Cao Cao's summons.","Forced into service in 208, he became Zhuge Liang's great rival and later seized power in Wei. His grandson founded the Jin dynasty.",["Faked illness to avoid Cao Cao","Held off Zhuge Liang","Seized power in Wei in 249"]),
'zhanghe':('張郃','Junyi','?–231',"A general of Yuan Shao who defected at Guandu.","A master of terrain, he beat Ma Su at Jieting in 228. He was killed by an arrow at Mumen.",["Defected at Guandu","Victory at Jieting","Five Elite Generals of Wei"]),
'xuhuang':('徐晃','Gongming','?–227',"A former officer of Yang Feng.","He broke Guan Yu's siege of Fancheng in 219. Cao Cao compared him to the famous Han general Zhou Yafu.",["Broke the siege of Fancheng","Compared to Zhou Yafu","Five Elite Generals of Wei"]),
'caopi':('曹丕','Zihuan','187–226',"Cao Cao's eldest surviving son and heir.","He took Lady Zhen at Ye, ended the Han dynasty in 220 and became the first emperor of Wei. He wrote one of China's first works of literary criticism.",["First emperor of Wei","Ended the Han dynasty","'Discourse on Literature'"]),
'caozhang':('曹彰','Ziwen','?–223',"Cao Cao's son, the 'Yellow Beard'.","Strong enough to wrestle wild beasts, he crushed the Wuhuan rebels in Dai in 218.",["'Yellow Beard'","Crushed the Wuhuan","Wrestled wild beasts"]),
'caohong':('曹洪','Zilian','?–232',"Cao Cao's cousin, rich and stingy.","At Xingyang in 190 he gave Cao Cao his own horse: 'The realm can do without Hong, not without you.'",["Saved Cao Cao at Xingyang","Wealthy and miserly","Fought at Hanzhong"]),
'caochun':('曹純','Zihe','?–210',"Cao Ren's younger brother.","He led the elite Tiger and Leopard Cavalry, killed Yuan Tan and caught Liu Bei's daughters at Changban.",["Tiger and Leopard Cavalry","Killed Yuan Tan","Pursuit at Changban"]),
'jiaxu':('賈詡','Wenhe','147–224',"A cunning strategist of Wuwei.","He twice beat Cao Cao while advising Zhang Xiu, then joined him and split Ma Chao and Han Sui at Tong Pass.",["Twice beat Cao Cao at Wancheng","Divided Ma Chao and Han Sui","Died old and safe"]),
'chengyu':('程昱','Zhongde','141–220',"A tall man with a fine beard from Dong commandery.","When Lü Bu seized Yan province in 194 he held the last three cities for Cao Cao.",["Held three cities against Lü Bu","Bold, stern adviser","Recruited Cao Cao's early army"]),
'xunyou':('荀攸','Gongda','157–214',"Xun Yu's nephew, quiet and brilliant.","He planned the flooding of Xiapi to capture Lü Bu and the raid that burned Yuan Shao's supplies at Guandu.",["Flooded Xiapi","Feint at Baima","Burned Wuchao at Guandu"]),
'wenpin':('文聘','Zhongye','?–?',"Liu Biao's guardian of the northern border.","He surrendered to Cao Cao in 208 with tears and then held the Jiangxia border against Wu for decades.",["Wept when surrendering","Held Jiangxia for Wei","Loyal to old and new lords"]),
'litong':('李通','Wenda','168–209',"A Runan strongman.","He refused Yuan Shao's bribes during Guandu and died in 209 going to relieve Cao Ren at Jiangling.",["Refused Yuan Shao's bribes","Kept Runan loyal","Died relieving Jiangling"]),
'caimao':('蔡瑁','Degui','?–?',"Liu Biao's brother-in-law.","He placed Liu Cong on the throne of Jing and surrendered it to Cao Cao in 208. In the novel Cao Cao executes him, tricked by a forged letter.",["Surrendered Jingzhou","Commanded the Jing navy","Executed by ruse (novel)"]),
'zhangyun':('張允','','?–?',"A relative of Liu Biao.","He commanded the Jing navy with Cai Mao. In the novel both are executed after Zhou Yu's forged-letter trick.",["Jing navy commander","Surrendered to Cao Cao","Executed by ruse (novel)"]),
'zangba':('臧霸','Xuangao','?–?',"A Taishan bandit chief.","He held the coast of Qing and Xu provinces for Cao Cao, keeping the east safe.",["Ruled the Taishan bandits","Guarded the eastern coast","Fought at Ruxu"]),
'zhuling':('朱靈','Wenbo','?–?',"An officer of Yuan Shao who joined Cao Cao.","Cao Cao trusted him, though he once handed his army to Yu Jin.",["Joined Cao Cao from Yuan Shao","Long service in Wei","Steady general"]),
'kuaiyue':('蒯越','Yidu','?–214',"A clever Jingzhou noble.","He helped Liu Biao take Jing by killing bandit chiefs at a feast, then urged surrender to Cao Cao, who said: 'I'm gladder to gain Kuai Yidu than Jingzhou.'",["Feast that won Jing for Liu Biao","Urged surrender to Cao Cao","Praised by Cao Cao"]),
'wangcan':('王粲','Zhongxuan','177–217',"A poet with a perfect memory.","He could rebuild a scattered game of Go stone by stone. One of the Seven Scholars of Jian'an, he urged Liu Cong to surrender.",["Seven Scholars of Jian'an","Perfect memory","'Ode on Climbing the Tower'"]),
'xushu':('徐庶','Yuanzhi','?–?',"A swordsman who turned scholar after avenging a friend.","He recommended Zhuge Liang to Liu Bei. When Cao Cao captured his mother in 208 he left Liu Bei for Wei. In the novel he vows never to give Cao Cao a plan.",["Recommended Zhuge Liang","Left Liu Bei for his mother","Silent in Cao Cao's service (novel)"]),
'yangling':('楊齡','','fictional',"A Changsha officer of Han Xuan.","In the novel he rode out against Guan Yu and was cut down in a few bouts.",["Han Xuan's officer","Challenged Guan Yu","Lost in a few bouts (novel)"],1),
'shamoke':('沙摩柯','','?–222',"Chieftain of the Wuling hill tribes.","He joined Liu Bei's war on Wu and fell at Xiaoting. The novel has him kill Gan Ning.",["Wuling tribal chief","Allied with Liu Bei","Killed Gan Ning (novel)"]),
'liuxian':('劉賢','','?–?',"Son of Liu Du of Lingling.","In the novel he fights for Lingling with Xing Daorong and is captured.",["Heir of Lingling","Captured by Liu Bei's men (novel)","Surrendered with his father"]),
'baolong':('鮑隆','','fictional',"A tiger-hunter of Guiyang.","In the novel he once killed two tigers. He plotted a false surrender to Zhao Yun and was killed.",["Killed two tigers","False surrender plot","Guiyang champion (novel)"],1),
'menghuo':('孟獲','','?–?',"A leader of the southern tribes of Nanzhong.","In 225 Zhuge Liang captured and released him seven times until he submitted for good. He later served Shu.",["Captured seven times by Zhuge Liang","King of the Nanman (novel)","Later a Shu official"]),
'liuba':('劉巴','Zichu','?–222',"A proud Lingling scholar.","He refused Liu Bei for years and fled to Jiaozhi, but later reformed Shu's coinage and wrote its state documents.",["Refused Liu Bei at first","Reformed Shu's currency","Drafted Shu's edicts"]),
'xianglang':('向朗','Julang','167–247',"A Xiangyang scholar, student of Sima Hui.","He served Liu Bei in Jingzhou and Shu and in old age became a famous book collector.",["Student of Sima Hui","Served Shu for decades","Famous library"]),
}
